from html.parser import HTMLParser
import pathlib
VOID={'meta','link','br','hr','img','input','source','area','base','col','embed','param','track','wbr'}
class P(HTMLParser):
    def __init__(s): super().__init__(); s.stack=[]; s.err=[]
    def handle_starttag(s,t,a):
        if t not in VOID: s.stack.append(t)
    def handle_endtag(s,t):
        if not s.stack: s.err.append(f'stray </{t}>'); return
        if s.stack[-1]!=t: s.err.append(f'mismatch: expected </{s.stack[-1]}> got </{t}> line {s.getpos()[0]}')
        else: s.stack.pop()
for f in sorted(pathlib.Path('public').rglob('*.html')):
    p=P(); p.feed(f.read_text())
    print(f, "OK" if not p.err and not p.stack else (p.err or p.stack))
